"use client";

import { loadFont as loadSerif } from "@remotion/google-fonts/InstrumentSerif";
import { loadFont as loadMono } from "@remotion/google-fonts/JetBrainsMono";
import { loadFont as loadManrope } from "@remotion/google-fonts/Manrope";
import type React from "react";
import { useEffect, useId, useMemo, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
} from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  type BracketIndexElementId,
  bracketIndexTimeline,
  DEFAULT_PRODUCT,
  DEFAULT_WORDS,
} from "./timeline";

const manrope = loadManrope("normal", {
  weights: ["500", "600"],
  subsets: ["latin"],
});
const serif = loadSerif("italic", { weights: ["400"], subsets: ["latin"] });
const mono = loadMono("normal", { weights: ["400"], subsets: ["latin"] });

const REMOCN_R_PATH =
  "M 0.01 0.81 C 0.01 1.73, 0.36 2.79, 1.09 4.13 C 4.91 11.04, 13.45 17.16, 21.7 18.9 C 22.94 19.16, 23.18 19.16, 51.39 19.27 C 76.07 19.36, 80.02 19.4, 81.32 19.57 C 89.89 20.69, 96.2 24.68, 99.38 31.01 C 103.19 38.56, 102.53 50.1, 97.91 57.07 C 94.66 61.96, 89.68 64.99, 83.26 66 C 82.81 66.07, 70.18 66.83, 55.2 67.69 C 24.82 69.43, 27.03 69.23, 24.18 70.4 C 19.9 72.15, 14.84 75.7, 10.65 79.89 C 4.86 85.68, 1.3 91.91, 0.25 98.13 C 0.12 98.85, 0.08 103.13, 0.04 116.66 L 0 134.26 9.5 134.26 L 19 134.26 19.05 119.41 C 19.1 103.27, 19.08 103.82, 19.82 101.04 C 21.79 93.65, 27.86 88.75, 36.45 87.63 C 37.23 87.53, 39.41 87.5, 43.57 87.53 C 50.12 87.59, 50.75 87.65, 53.22 88.45 C 56.61 89.56, 59.67 91.86, 62.02 95.07 C 62.52 95.76, 69.35 103.85, 77.2 113.07 C 85.04 122.28, 91.63 130.04, 91.85 130.32 C 92.07 130.59, 92.5 131.34, 92.82 131.97 C 93.52 133.35, 94.11 133.93, 95.06 134.13 C 95.5 134.23, 98.97 134.26, 106.36 134.23 L 117.01 134.19 100.82 113.07 C 91.91 101.45, 84.52 91.78, 84.39 91.57 C 83.36 89.89, 83.66 87.53, 85.09 86 C 85.79 85.25, 86.36 84.94, 88.07 84.38 C 96.18 81.72, 104.15 76.62, 109.97 70.36 C 120.59 58.93, 124.06 44.32, 119.44 30.43 C 114.59 15.81, 101.93 4.02, 87.64 0.83 C 83.93 0.01, 88.09 0.08, 41.85 0.04 L 0.01 0 0.01 0.81 Z";
const R_W = 124.06;
const R_H = 134.26;
// The remocn.dev logo: R mark 0.76em tall on the baseline, then "emocn" in
// Manrope 600 at -0.025em. Manrope's baseline sits 0.883em into a 1em line box.
const LOGO_R = 0.76;
const LOGO_GAP = 0.04;
const LOGO_TRACK = -0.025;
const BASELINE = 0.883;

export interface BracketIndexProps {
  /** Text set before the brackets; it steps aside for the product name. */
  prefix?: string;
  /** Words indexed inside the brackets, in order. */
  words?: string[];
  /** Final word the brackets close on. */
  product?: string;
  accent?: string;
  /** Text color of the words and prefix; overrides the theme ink. */
  ink?: string;
  /** Background fill; "transparent" drops it. */
  background?: string;
  /** Typeface for the indexed words. Load it yourself; Manrope by default. */
  fontFamily?: string;
  /** Weight of the indexed words. */
  fontWeight?: number;
  /** Frames each word holds in the brackets before the next rolls in. */
  hold?: number;
  /** Replaces the remocn mark when `product` is "remocn". */
  logo?: React.ReactNode;
  /** Size of the brackets and words, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  theme?: "dark" | "light";
  speed?: number;
  /**
   * Moves, trims or stretches the brackets' intro, single words and the
   * product name, by the ids in `./timeline`.
   * Frames on the scene timeline, after `delay` and `speed`.
   */
  timing?: Timing<BracketIndexElementId>;
}

const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IO = Easing.bezier(0.7, 0, 0.2, 1);
const EASE_SNAP = Easing.bezier(0.22, 1.12, 0.36, 1);

const WEIGHT = 500;
const TRACK = -0.03;
const SERIF_TRACK = -0.01;
const PAD = 0.2;
const GAP = 0.26;

// gradients.sh "beam" palette (#f4f7ff #8fb4ff #3d5bff #1a1660), with the
// accent standing in for #3d5bff. Dark runs light→accent, light runs accent→deep.
const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F3F2EF",
    rest: "#77767C",
    beam: ["#F4F7FF", "#8FB4FF", ""],
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    rest: "#8E8C86",
    beam: ["", "#2B37C9", "#1A1660"],
  },
} as const;

function isLogo(word: string) {
  return word.trim().toLowerCase() === "remocn";
}

/** Widths in em: [prefix (serif italic), ...items (Manrope, or the logo)]. */
function useWidths(strings: string[], family: string, weight: number) {
  const [widths, setWidths] = useState<number[] | null>(null);
  const [handle] = useState(() => delayRender("bracket-index: measuring"));
  const released = useRef(false);
  const key = strings.join("\u0000");

  useEffect(() => {
    let live = true;
    const sans = `${weight} 100px "${family}"`;
    const logo = `600 100px "${manrope.fontFamily}"`;
    const italic = `italic 400 100px "${serif.fontFamily}"`;
    Promise.all([
      manrope.waitUntilDone(),
      serif.waitUntilDone(),
      document.fonts.load(sans),
      document.fonts.load(logo),
      document.fonts.load(italic),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        const ctx = document.createElement("canvas").getContext("2d");
        const run = (s: string, font: string, track: number) => {
          if (!ctx) return s.length * 0.55;
          ctx.font = font;
          return ctx.measureText(s).width / 100 + track * [...s].length;
        };
        setWidths(
          key.split("\u0000").map((s, i) => {
            if (i === 0) return run(s, italic, SERIF_TRACK);
            if (isLogo(s)) {
              return (
                (LOGO_R * R_W) / R_H + LOGO_GAP + run("emocn", logo, LOGO_TRACK)
              );
            }
            return run(s, sans, TRACK);
          }),
        );
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle, family, weight]);

  return widths;
}

function pad2(n: number) {
  return String(n).padStart(2, "0");
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function BracketIndex(props: BracketIndexProps) {
  const {
    prefix = "Motion for",
    words = DEFAULT_WORDS,
    product = DEFAULT_PRODUCT,
    accent = "#3B5BFD",
    ink,
    background,
    fontFamily = manrope.fontFamily,
    fontWeight = WEIGHT,
    logo,
    scale = 1,
    delay = 0,
    theme = "dark",
    speed = 1,
    timing,
  } = props;
  const glide = useGlide();
  const now = useSceneFrame();
  const fAt = (n: number) => Math.max(0, n - delay) * speed;
  const frame = fAt(now);
  /** Whether a value in px, as a function of time, moves on this frame. */
  const stirs = (v: (f: number) => number) => {
    const here = v(frame);
    return (
      Math.abs(v(fAt(now + 1)) - here) > 1e-3 ||
      Math.abs(here - v(fAt(now - 1))) > 1e-3
    );
  };
  const { width, height, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    bracketIndexTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const t = THEMES[theme];
  const fg = ink ?? t.fg;
  const stage = background ?? t.bg;
  const fill = stage === "transparent" ? undefined : stage;
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const beam = t.beam.map((c) => c || accent);

  const items = useMemo(() => [...words, product], [words, product]);
  const widths = useWidths(
    useMemo(() => [prefix, ...items], [prefix, items]),
    fontFamily,
    fontWeight,
  );

  // Swap i brings items[i] in. Swap 0 is the bracket opening.
  const swaps = useMemo(
    () =>
      items.map((_, i) =>
        tl.get(i === items.length - 1 ? "product" : `word:${i}`),
      ),
    [tl, items],
  );
  const starts = swaps.map((e) => e.start);
  const intro = tl.get("intro");

  if (!widths)
    return <div style={{ position: "absolute", inset: 0, background: fill }} />;

  const prefixW = widths[0];
  const itemW = widths.slice(1);
  const last = items.length - 1;

  const stroke = 0.022;
  const boxOf = (slot: number) => 2 * stroke + 2 * PAD + slot;
  const widest = Math.max(
    ...itemW.map((w, i) => boxOf(w) + (i === last ? 0 : prefixW + GAP)),
  );

  // The brackets always hold the wider of the two words: a longer word
  // gets room before it rolls in, a shorter one is closed on after.
  const rollAt = (i: number) =>
    i > 0 && itemW[i] > itemW[i - 1]
      ? starts[i] + swaps[i].beat("rollWait")
      : starts[i];
  let slot = 0;
  for (let i = 0; i < items.length; i++) {
    if (frame < starts[i]) break;
    if (i === 0) {
      slot =
        itemW[0] *
        interpolate(
          frame,
          [starts[0], starts[0] + swaps[0].beat("open")],
          [0, 1],
          {
            ...CLAMP,
            easing: EASE_SNAP,
          },
        );
      continue;
    }
    const from = itemW[i - 1];
    const resizeAt =
      itemW[i] > from ? starts[i] : starts[i] + swaps[i].beat("resizeWait");
    const p = interpolate(
      frame,
      [resizeAt, resizeAt + swaps[i].beat("resize")],
      [0, 1],
      {
        ...CLAMP,
        easing: EASE_IO,
      },
    );
    slot = from + (itemW[i] - from) * p;
  }

  const finalAt = (f: number) =>
    interpolate(f, [swaps[last].start, swaps[last].end], [0, 1], {
      ...CLAMP,
      easing: EASE_IO,
    });
  const finalP = finalAt(frame);
  const presence = 1 - finalP;
  // The product name lands bigger than the indexed words: a poster frame.
  const sizeA = Math.min(height * 0.15, (width * 0.84) / widest);
  const sizeB = Math.min(height * 0.27, (width * 0.6) / boxOf(itemW[last]));
  const sizeOf = (p: number) => sizeA + (sizeB - sizeA) * p;
  const size = sizeOf(finalP);
  const box = boxOf(slot);
  const total = presence * (prefixW + GAP) + box;

  const cx = width / 2;
  const cy = height / 2;
  const em = (v: number) => v * size;
  const groupLeft = cx - em(total) / 2;
  const bracketL = groupLeft + em(presence * (prefixW + GAP));
  const bracketR = bracketL + em(box);
  const slotCenter = (bracketL + bracketR) / 2;

  const introAt = (f: number) =>
    interpolate(f, [intro.start, intro.end], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
  const introP = introAt(frame);
  const half = em(0.8) * (0.7 + 0.3 * introP);
  const arm = em(0.2) * introP;
  const sw = Math.max(1.5, sizeA * stroke);
  // Lowercase words sit below cap center; nudge the frame toward x-height.
  const top = cy + em(0.04) - half;
  const bottom = cy + em(0.04) + half;
  const lineTop = cy - em(0.5);

  const bracketPath = (x: number, dir: 1 | -1) => {
    const xi = x + (dir * sw) / 2;
    return `M ${xi + dir * arm} ${top + sw / 2} H ${xi} V ${bottom - sw / 2} H ${xi + dir * arm}`;
  };

  const prefixOpacity =
    interpolate(frame, [intro.start, intro.end], [0.15, 1], CLAMP) *
    interpolate(presence, [0.45, 1], [0, 1], CLAMP);
  const riseAt = (f: number) =>
    interpolate(
      f,
      [intro.start, intro.start + intro.beat("rise")],
      [sizeOf(finalAt(f)) * 0.14, 0],
      {
        ...CLAMP,
        easing: EASE_OUT,
      },
    );
  const prefixRise = riseAt(frame);
  // While the product name lands, the type grows. Layout rounds a box and a
  // baseline to whole pixels, so the line rode `top` and the font size in
  // uneven steps. The prefix and the words are laid out once, at the size
  // each rests at longest, and placed and grown by a transform; the word strip
  // is laid out where the product name rests and rides a transform too. One
  // layout for their whole life: a frame that hands text from a transform to
  // layout snaps it to a whole pixel.
  const growing = stirs((f) => sizeOf(finalAt(f)) * (prefixW + GAP + 1.14));
  const lineTopA = height / 2 - sizeA * 0.5;
  const stripRest = height / 2 - sizeB * 0.5 - sizeB * 0.02;

  const textStyle: React.CSSProperties = {
    position: "absolute",
    top: 0,
    fontFamily,
    fontWeight,
    fontSize: size,
    lineHeight: 1,
    letterSpacing: `${TRACK}em`,
    whiteSpace: "nowrap",
    color: fg,
    fontKerning: "normal",
  };

  // Words ride one strip through the slit, like an odometer: the outgoing
  // word and the incoming one never share the window.
  const roll = (i: number, f = frame) =>
    interpolate(f, [rollAt(i), rollAt(i) + swaps[i].beat("roll")], [0, 1], {
      ...CLAMP,
      easing: EASE_IO,
    });
  const travel = 1.16;
  // The gradient turns a touch over the shot; never more than that.
  const drift = interpolate(frame, [0, 180], [0, 1], CLAMP);
  const wordLayers = items.map((word, i) => {
    const s = starts[i];
    const enterAt = (f: number) =>
      i === 0
        ? interpolate(f, [s, s + swaps[0].beat("open")], [0, 1], {
            ...CLAMP,
            easing: EASE_OUT,
          })
        : roll(i, f);
    const enter = enterAt(frame);
    const exit = i < last ? roll(i + 1) : 0;
    if (frame < s || exit >= 1) return null;
    const yAt = (f: number) => {
      const k = sizeOf(finalAt(f));
      const out = i < last ? roll(i + 1, f) : 0;
      return (
        (i === 0 ? 0.1 * k : travel * k) * (1 - enterAt(f)) - travel * k * out
      );
    };
    const y =
      (i === 0 ? em(0.1) : em(travel)) * (1 - enter) - em(travel) * exit;
    // The word also grows with the product name's landing, which moves its
    // baseline even where the ride itself is over.
    const tilt = glide(stirs(yAt) || stirs((f) => sizeOf(finalAt(f)) * 1.14));
    // The product name rests at the landed size, every other word before it.
    const own = i === last ? sizeB : sizeA;
    const grow = `scale(${size / own})`;
    // The slot's centre is still at either size, and slides between them.
    const ownCenter = cx + (i === last ? 0 : (sizeA * (prefixW + GAP)) / 2);
    const ride = `translate(calc(-50% + ${slotCenter - ownCenter}px), ${y}px)`;
    // Dim whichever word is leaving the slit so the stacked frames stay quiet.
    const opacity =
      (i === 0 ? 0.35 + 0.65 * enter : 0.25 + 0.75 * enter) *
      (1 - Math.min(1, exit / 0.6));
    if (isLogo(word) && logo) {
      return (
        <div
          key={word + String(i)}
          style={{
            position: "absolute",
            top: 0,
            left: ownCenter,
            height: own * 1.14,
            display: "flex",
            alignItems: "center",
            transformOrigin: "50% 0",
            transform: `${ride} ${grow}${tilt}`,
            opacity,
          }}
        >
          {logo}
        </div>
      );
    }
    if (isLogo(word)) {
      const lem = (v: number) => v * own;
      const lw = lem(itemW[i]);
      const rh = lem(LOGO_R);
      const base = lem(BASELINE);
      return (
        <svg
          key={word + String(i)}
          width={lw}
          height={lem(1.14)}
          style={{
            position: "absolute",
            top: 0,
            left: ownCenter,
            overflow: "visible",
            transformOrigin: "50% 0",
            transform: `${ride} ${grow}${tilt}`,
            opacity,
          }}
          aria-hidden
        >
          <path
            d={REMOCN_R_PATH}
            fill={`url(#${uid}-logo)`}
            transform={`translate(0 ${base - rh}) scale(${rh / R_H})`}
          />
          <text
            x={(rh * R_W) / R_H + lem(LOGO_GAP)}
            y={base}
            fill={`url(#${uid}-logo)`}
            fontFamily={manrope.fontFamily}
            fontWeight={600}
            fontSize={own}
            letterSpacing={`${LOGO_TRACK}em`}
            style={{ fontKerning: "normal" }}
          >
            emocn
          </text>
          <defs>
            <linearGradient
              id={`${uid}-logo`}
              gradientUnits="userSpaceOnUse"
              x1={lw * (0.05 + 0.1 * drift)}
              y1={base - lem(0.95)}
              x2={lw * (0.95 - 0.1 * drift)}
              y2={base + lem(0.2)}
            >
              <stop offset="0" stopColor={beam[0]} />
              <stop offset="0.5" stopColor={beam[1]} />
              <stop offset="1" stopColor={beam[2]} />
            </linearGradient>
          </defs>
        </svg>
      );
    }
    return (
      <div
        key={word + String(i)}
        style={{
          ...textStyle,
          left: ownCenter,
          fontSize: own,
          transformOrigin: "50% 0",
          transform: `${ride} ${grow}${tilt}`,
          opacity,
        }}
      >
        {word}
      </div>
    );
  });

  const innerL = bracketL + sw + em(0.04);
  const innerR = bracketR - sw - em(0.04);

  // Counter: two-digit index that rolls on every swap.
  const counterSize = Math.max(12, sizeA * 0.2);
  const counterInAt = (f: number) =>
    interpolate(
      f,
      [
        starts[0] + swaps[0].beat("counterAt"),
        starts[0] + swaps[0].beat("counterAt") + swaps[0].beat("counter"),
      ],
      [0, 1],
      {
        ...CLAMP,
        easing: EASE_OUT,
      },
    );
  const counterIn = counterInAt(frame);
  // The counter rides the bracket's top edge, which moves as the bracket opens
  // and as the product name grows. Layout holds where it finally rests and
  // the ride is a transform: layout rounds a baseline to whole
  // pixels, so a counter eased by `top` clicks along pixel by pixel.
  const counterTop = (p: number, i: number) => {
    const k = sizeOf(p);
    return cy + k * 0.04 - k * 0.8 * (0.7 + 0.3 * i) - counterSize * 1.75;
  };
  const counterRest = counterTop(1, 1);
  const counterLift = (f: number) =>
    (1 - counterInAt(f)) * counterSize * 0.5 +
    counterTop(finalAt(f), introAt(f)) -
    counterRest;
  const counterMoving = stirs(counterLift);
  const counterRows = items.map((_, i) => {
    const s = starts[i];
    const intoAt = (f: number) =>
      i === 0
        ? 1
        : interpolate(
            f,
            [
              s + swaps[i].beat("indexAt"),
              s + swaps[i].beat("indexAt") + swaps[i].beat("index"),
            ],
            [0, 1],
            {
              ...CLAMP,
              easing: EASE_OUT,
            },
          );
    const outAt = (f: number) =>
      i < last
        ? interpolate(
            f,
            [starts[i + 1], starts[i + 1] + swaps[i + 1].beat("indexOut")],
            [0, 1],
            {
              ...CLAMP,
              easing: EASE_IO,
            },
          )
        : 0;
    const into = intoAt(frame);
    const out = outAt(frame);
    if ((i > 0 && frame < s + swaps[i].beat("indexAt")) || out >= 1)
      return null;
    const lift = (f: number) =>
      (1 - intoAt(f)) * counterSize * 1.1 - outAt(f) * counterSize * 1.1;
    return (
      <div
        key={`c${String(i)}`}
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          transform: `translateY(${(1 - into) * counterSize * 1.1 - out * counterSize * 1.1}px)${glide(stirs(lift) && !counterMoving)}`,
          opacity: into * (1 - out),
        }}
      >
        {pad2(i + 1)}
      </div>
    );
  });

  return (
    <AbsoluteFill style={{ background: fill, overflow: "hidden" }}>
      <div
        style={{
          position: "absolute",
          inset: 0,
          opacity: EASE_OUT(finalP),
          background:
            theme === "dark"
              ? `radial-gradient(64% 62% at ${46 + 8 * drift}% 122%, color-mix(in oklab, ${beam[1]} 46%, transparent) 0%, color-mix(in oklab, ${beam[2]} 34%, transparent) 38%, color-mix(in oklab, #1A1660 26%, transparent) 62%, transparent 86%)`
              : `radial-gradient(64% 62% at ${46 + 8 * drift}% 122%, color-mix(in oklab, #8FB4FF 58%, transparent) 0%, color-mix(in oklab, #8FB4FF 22%, transparent) 50%, transparent 84%)`,
        }}
      />
      <ScaleLayer scale={scale}>
        <div
          style={{
            ...textStyle,
            fontFamily: serif.fontFamily,
            fontStyle: "italic",
            fontWeight: 400,
            letterSpacing: `${SERIF_TRACK}em`,
            left: bracketL - em(GAP + prefixW),
            top: lineTopA,
            fontSize: sizeA,
            transformOrigin: "0 0",
            transform: `translateY(${lineTop - lineTopA + prefixRise}px) scale(${size / sizeA})${glide(growing || stirs(riseAt))}`,
            opacity: prefixOpacity,
          }}
        >
          {prefix}
        </div>

        <div
          style={{
            position: "absolute",
            left: 0,
            width,
            top: stripRest,
            transform: `translateY(${lineTop - em(0.02) - stripRest}px)`,
            height: em(1.14),
            overflow: "hidden",
            clipPath: `inset(0 ${width - innerR}px 0 ${innerL}px)`,
          }}
        >
          <div
            style={{
              position: "absolute",
              left: 0,
              top: sizeB * 0.02,
              transform: `translateY(${em(0.02) - sizeB * 0.02}px)`,
              width,
            }}
          >
            {wordLayers}
          </div>
        </div>

        <svg
          width={width}
          height={height}
          style={{ position: "absolute", inset: 0 }}
          aria-hidden
        >
          <defs>
            <linearGradient
              id={`${uid}-bracket`}
              gradientUnits="userSpaceOnUse"
              x1={0}
              y1={top}
              x2={0}
              y2={bottom}
            >
              <stop offset="0" stopColor={beam[0]} />
              <stop offset="0.55" stopColor={beam[1]} />
              <stop offset="1" stopColor={beam[2]} />
            </linearGradient>
          </defs>
          <g
            fill="none"
            stroke={`url(#${uid}-bracket)`}
            strokeWidth={sw}
            strokeLinecap="butt"
            strokeLinejoin="miter"
            opacity={interpolate(introP, [0, 1], [0.2, 1])}
          >
            <path d={bracketPath(bracketL, 1)} />
            <path d={bracketPath(bracketR, -1)} />
          </g>
        </svg>

        <div
          style={{
            position: "absolute",
            left: bracketL,
            top: counterRest,
            height: counterSize * 1.2,
            display: "flex",
            alignItems: "center",
            fontFamily: mono.fontFamily,
            fontWeight: 400,
            fontSize: counterSize,
            lineHeight: 1,
            letterSpacing: "0.02em",
            fontVariantNumeric: "tabular-nums",
            color: t.rest,
            opacity: counterIn,
            transform: `translateY(${counterLift(frame)}px)${glide(counterMoving)}`,
            whiteSpace: "nowrap",
          }}
        >
          <span>[</span>
          <span
            style={{
              position: "relative",
              display: "inline-block",
              width: "1.2em",
              height: counterSize * 1.2,
              overflow: "hidden",
              top: counterSize * 0.1,
            }}
          >
            {counterRows}
          </span>
          <span>]</span>
        </div>
      </ScaleLayer>
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The brackets draw in beside the prefix, open on the first word, roll
// through the words like an odometer and close on the product name, which
// lands bigger. Frames on the 30 fps scene timeline, after `delay` and
// `speed`. The ids are public: a saved `timing` prop refers to them.

export type BracketIndexElementId = "intro" | `word:${number}` | "product";

export interface BracketIndexTimingProps {
  words?: string[];
  product?: string;
  hold?: number;
}

export const DEFAULT_WORDS = ["launches", "changelogs", "demos"];
export const DEFAULT_PRODUCT = "remocn";
const INTRO = 10;
const RISE = 12;
const OPEN_AT = 6;
const OPEN_LEN = 16;
const HOLD = 22;
const SWAP = 16;
const ROLL = 8;
const RESIZE = 8;
const FINAL_SWAP = 20;
/** The counter's first index fades in this far into the opening, over 10. */
const COUNTER_AT = 8;
const COUNTER = 10;
/** A later index rolls in this far into its swap, over `COUNTER`. */
const INDEX_AT = 2;
/** The outgoing index rolls out over this many frames. */
const INDEX_OUT = 8;

// A word runs until the next one rolls in. A wider word rolls in once the
// brackets have made room for it (`rollWait`); a narrower one rolls in at
// once and the brackets close on it after (`resizeWait`).
export const bracketIndexTimeline = defineTimeline<
  BracketIndexElementId,
  BracketIndexTimingProps
>(({ words = DEFAULT_WORDS, product = DEFAULT_PRODUCT, hold = HOLD }) => {
  const items = [...words, product];
  const last = items.length - 1;
  const starts = [OPEN_AT];
  for (let i = 1; i < items.length; i++) {
    starts.push(starts[i - 1] + (i === 1 ? OPEN_LEN : SWAP) + hold);
  }
  const swapBeats = {
    roll: ROLL,
    resize: RESIZE,
    rollWait: RESIZE - 2,
    resizeWait: ROLL - 1,
    indexAt: INDEX_AT,
    index: COUNTER,
    indexOut: INDEX_OUT,
  };
  const elements: TimelineElement<BracketIndexElementId>[] = [
    {
      id: "intro",
      lane: "Brackets",
      label: "brackets",
      start: 0,
      length: INTRO,
      beats: { rise: RISE },
    },
  ];
  items.forEach((word, i) => {
    elements.push({
      id: i === last ? "product" : `word:${i}`,
      lane: "Words",
      label: word,
      start: starts[i],
      length: i === last ? FINAL_SWAP : starts[i + 1] - starts[i],
      follows: i > 0 ? `word:${i - 1}` : undefined,
      beats:
        i === 0
          ? {
              open: OPEN_LEN,
              counterAt: COUNTER_AT,
              counter: COUNTER,
            }
          : swapBeats,
    });
  });
  return elements;
});
